mapper.select:
select project_id, work_week, exceptions, update_by, update_time
from sys_project_work_calendar
where project_id = #{projectId}

mapper.update:
update sys_project_work_calendar
set work_week = #{workWeek,typeHandler=com.cat2bug.system.mybatis.IntegerListJsonTypeHandler},
    exceptions = #{exceptions,typeHandler=com.cat2bug.system.mybatis.StringStringMapJsonTypeHandler},
    update_by = #{updateBy},
    update_time = #{updateTime}
where project_id = #{projectId}
